import{_ as o,a as s,c as a,ac as r}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第46–52课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第46–52课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第39–45课","link":"/life/english/new-concept/book-1/review-part-06"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第53–59课","link":"/life/english/new-concept/book-1/review-part-08"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第39–45课","link":"/life/english/new-concept/book-1/review-part-06"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第53–59课","link":"/life/english/new-concept/book-1/review-part-08"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-07.md","filePath":"life/english/new-concept/book-1/review-part-07.md"}'),t={name:"life/english/new-concept/book-1/review-part-07.md"};function n(i,e,l,c,p,d){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第46–52课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第46–52课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第46–52课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第46–52课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-46-·-can-表能力" tabindex="-1">Lesson 46 · can 表能力 <a class="header-anchor" href="#lesson-46-·-can-表能力" aria-label="Permalink to &quot;Lesson 46 · can 表能力 {#lesson-46-·-can-表能力}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Can you print the report today?</p><h3 id="练习-1-45" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-45" aria-label="Permalink to &quot;练习 1 {#练习-1-45}&quot;">​</a></h3><p>将 You can print it. 改为一般疑问句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Can you print it?</p><p><strong>解析：</strong> 按本课规则判断：can 后接动词原形，对所有人称保持 can，不增加 s。否定为 cannot 或 can&#39;t；问句把 can 放在主语前，不另加 do。can 表能力时说明能否完成动作，不等于动作正在发生。副词可说明做得怎样，如 type quickly；形容词常用于描述人或物。</p></details><p><strong>表达迁移：</strong> 围绕“说明能够完成的工作”写两至三句，再读给同伴听。至少使用一次can 表能力，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Can you print the report today? My colleague can translate this message.</p><p>Can 前置形成问句，you 为主语，print 为原形；today 说明希望完成任务的时间。 My colleague 是第三人称单数，但 can 不加 s；translate 用原形，this message 为宾语。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-046">回看本课</a></p><h2 id="lesson-47-·-实义动词的一般现在时问句" tabindex="-1">Lesson 47 · 实义动词的一般现在时问句 <a class="header-anchor" href="#lesson-47-·-实义动词的一般现在时问句" aria-label="Permalink to &quot;Lesson 47 · 实义动词的一般现在时问句 {#lesson-47-·-实义动词的一般现在时问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Do you like coffee without sugar?</p><h3 id="练习-1-46" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-46" aria-label="Permalink to &quot;练习 1 {#练习-1-46}&quot;">​</a></h3><p>填助动词：___ you like coffee?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Do</p><p><strong>解析：</strong> 按本课规则判断：主语为 I/you/we/they 时，实义动词的一般现在时问句通常借助 do；否定用 don&#39;t + 原形。like 表较稳定的喜好，want 表当前想要。Do you like tea? 与 Do you want some tea? 关注点不同。不要在实义动词前错误加 be；回答时用 Yes, I do，不重复整个宾语。</p></details><p><strong>表达迁移：</strong> 围绕“询问饮食喜好和即时需求”写两至三句，再读给同伴听。至少使用一次实义动词的一般现在时问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Do you like coffee without sugar? I do not want a cold drink now.</p><p>Do 帮助 like 形成一般疑问句；coffee 是宾语，without sugar 修饰所说的咖啡，表示不加糖。 I do not want 是一般现在时否定；want 保持原形，a cold drink 为宾语，now 说明当前需求。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-047">回看本课</a></p><h2 id="lesson-48-·-实义动词的一般现在时问句" tabindex="-1">Lesson 48 · 实义动词的一般现在时问句 <a class="header-anchor" href="#lesson-48-·-实义动词的一般现在时问句" aria-label="Permalink to &quot;Lesson 48 · 实义动词的一般现在时问句 {#lesson-48-·-实义动词的一般现在时问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I do not want a cold drink now.</p><h3 id="练习-1-47" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-47" aria-label="Permalink to &quot;练习 1 {#练习-1-47}&quot;">​</a></h3><p>补否定：I ___ not want a cold drink.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> do</p><p><strong>解析：</strong> 按本课规则判断：主语为 I/you/we/they 时，实义动词的一般现在时问句通常借助 do；否定用 don&#39;t + 原形。like 表较稳定的喜好，want 表当前想要。Do you like tea? 与 Do you want some tea? 关注点不同。不要在实义动词前错误加 be；回答时用 Yes, I do，不重复整个宾语。</p></details><p><strong>表达迁移：</strong> 围绕“询问饮食喜好和即时需求”写两至三句，再读给同伴听。至少使用一次实义动词的一般现在时问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I do not want a cold drink now. Do you like coffee without sugar?</p><p>I do not want 是一般现在时否定；want 保持原形，a cold drink 为宾语，now 说明当前需求。 Do 帮助 like 形成一般疑问句；coffee 是宾语，without sugar 修饰所说的咖啡，表示不加糖。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-048">回看本课</a></p><h2 id="lesson-49-·-第三人称单数与-does" tabindex="-1">Lesson 49 · 第三人称单数与 does <a class="header-anchor" href="#lesson-49-·-第三人称单数与-does" aria-label="Permalink to &quot;Lesson 49 · 第三人称单数与 does {#lesson-49-·-第三人称单数与-does}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My brother prefers fish to beef.</p><h3 id="练习-1-48" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-48" aria-label="Permalink to &quot;练习 1 {#练习-1-48}&quot;">​</a></h3><p>填动词：My brother ___ (prefer) fish.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> prefers</p><p><strong>解析：</strong> 按本课规则判断：一般现在时主语为 he/she/it 或单个姓名时，肯定句实义动词通常加 s/es。变疑问或否定时由 does 承担人称变化，后面动词恢复原形：Does she like ...? / She doesn&#39;t like ...。不能同时让 does 和 likes 都标记第三人称。meat 通常是不可数名词，谈一类肉不用复数。</p></details><p><strong>表达迁移：</strong> 围绕“购买食物时表达家人的喜好”写两至三句，再读给同伴听。至少使用一次第三人称单数与 does，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My brother prefers fish to beef. Does your daughter eat carrots?</p><p>My brother 是单数主语，prefer 加 s；prefer A to B 表示在两者之间偏爱 A，to 不是不定式标记。 Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-049">回看本课</a></p><h2 id="lesson-50-·-第三人称单数与-does" tabindex="-1">Lesson 50 · 第三人称单数与 does <a class="header-anchor" href="#lesson-50-·-第三人称单数与-does" aria-label="Permalink to &quot;Lesson 50 · 第三人称单数与 does {#lesson-50-·-第三人称单数与-does}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Does your daughter eat carrots?</p><h3 id="练习-1-49" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-49" aria-label="Permalink to &quot;练习 1 {#练习-1-49}&quot;">​</a></h3><p>填原形：Does she ___ (eat) carrots?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> eat</p><p><strong>解析：</strong> 按本课规则判断：一般现在时主语为 he/she/it 或单个姓名时，肯定句实义动词通常加 s/es。变疑问或否定时由 does 承担人称变化，后面动词恢复原形：Does she like ...? / She doesn&#39;t like ...。不能同时让 does 和 likes 都标记第三人称。meat 通常是不可数名词，谈一类肉不用复数。</p></details><p><strong>表达迁移：</strong> 围绕“购买食物时表达家人的喜好”写两至三句，再读给同伴听。至少使用一次第三人称单数与 does，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Does your daughter eat carrots? My brother prefers fish to beef.</p><p>Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。 My brother 是单数主语，prefer 加 s；prefer A to B 表示在两者之间偏爱 A，to 不是不定式标记。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-050">回看本课</a></p><h2 id="lesson-51-·-come-from-与国籍表达" tabindex="-1">Lesson 51 · come from 与国籍表达 <a class="header-anchor" href="#lesson-51-·-come-from-与国籍表达" aria-label="Permalink to &quot;Lesson 51 · come from 与国籍表达 {#lesson-51-·-come-from-与国籍表达}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My neighbours come from Portugal.</p><h3 id="练习-1-50" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-50" aria-label="Permalink to &quot;练习 1 {#练习-1-50}&quot;">​</a></h3><p>补助动词：Where ___ your neighbours come from?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> do</p><p><strong>解析：</strong> 按本课规则判断：come from 是实义动词结构，一般现在时问句用 do/does；be from 用 be 提问。Where do you come from? 与 Where are you from? 都可询问来源，但不能混成 Where are you come from?。描述气候常用一般现在时，it 可作天气主语；sunny 等形容词与 rains 等动词结构要区分。</p></details><p><strong>表达迁移：</strong> 围绕“谈论国家与典型气候”写两至三句，再读给同伴听。至少使用一次come from 与国籍表达，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My neighbours come from Portugal. It is often windy here in spring.</p><p>My neighbours 是复数主语，come 不加 s；from Portugal 是来源信息，不能把 come 换成 are come。 It 是天气主语；is 后放频率副词 often，windy 为表语。in spring 说明季节，不用 on。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-051">回看本课</a></p><h2 id="lesson-52-·-come-from-与国籍表达" tabindex="-1">Lesson 52 · come from 与国籍表达 <a class="header-anchor" href="#lesson-52-·-come-from-与国籍表达" aria-label="Permalink to &quot;Lesson 52 · come from 与国籍表达 {#lesson-52-·-come-from-与国籍表达}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It is often windy here in spring.</p><h3 id="练习-1-51" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-51" aria-label="Permalink to &quot;练习 1 {#练习-1-51}&quot;">​</a></h3><p>补 be：It ___ often windy.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：come from 是实义动词结构，一般现在时问句用 do/does；be from 用 be 提问。Where do you come from? 与 Where are you from? 都可询问来源，但不能混成 Where are you come from?。描述气候常用一般现在时，it 可作天气主语；sunny 等形容词与 rains 等动词结构要区分。</p></details><p><strong>表达迁移：</strong> 围绕“谈论国家与典型气候”写两至三句，再读给同伴听。至少使用一次come from 与国籍表达，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>It is often windy here in spring. My neighbours come from Portugal.</p><p>It 是天气主语；is 后放频率副词 often，windy 为表语。in spring 说明季节，不用 on。 My neighbours 是复数主语，come 不加 s；from Portugal 是来源信息，不能把 come 换成 are come。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-052">回看本课</a></p>',60)])])}const u=o(t,[["render",n]]);export{m as __pageData,u as default};
